import java.lang.annotation.*;
import java.lang.reflect.*;

public class Main {
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD) @interface PreDestroy {}
    interface DisposableBean { void destroy(); }

    static class Bean implements DisposableBean {
        StringBuilder seq = new StringBuilder();
        @PreDestroy void pd() { seq.append("preDestroy;"); }
        public void destroy() { seq.append("disposableBean;"); }
        void destroyMethod() { seq.append("destroyMethod;"); }
        String seq() { return seq.toString(); }
    }

    public static void main(String[] args) throws Exception {
        Bean b = new Bean();
        for (Method m : Bean.class.getDeclaredMethods()) if (m.isAnnotationPresent(PreDestroy.class)) m.invoke(b);
        b.destroy();
        Bean.class.getDeclaredMethod("destroyMethod").invoke(b);
        System.out.println(b.seq());
    }
}
